import { create } from "zustand"
import type { Form, Submission } from "@/types"
import formsData from "@/data/forms.json"
import submissionsData from "@/data/submissions.json"

interface FormsState {
  forms: Form[]
  submissions: Submission[]

  getForms: () => Form[]
  getFormById: (id: string) => Form | undefined
  getSubmissionsByFormId: (formId: string) => Submission[]

  createForm: (form: Omit<Form, "id" | "createdAt" | "updatedAt">) => Form
  updateForm: (id: string, updates: Partial<Form>) => void
  deleteForm: (id: string) => void
  duplicateForm: (id: string) => Form | undefined

  addSubmission: (submission: Omit<Submission, "id" | "submittedAt">) => Submission
}

export const useFormsStore = create<FormsState>((set, get) => ({
  forms: formsData as Form[],
  submissions: submissionsData as Submission[],

  getForms: () => get().forms,

  getFormById: (id) => get().forms.find((form) => form.id === id),

  getSubmissionsByFormId: (formId) => get().submissions.filter((sub) => sub.formId === formId),

  createForm: (formData) => {
    const newForm: Form = {
      ...formData,
      id: `form-${Date.now()}`,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    }

    set((state) => ({
      forms: [...state.forms, newForm],
    }))

    return newForm
  },

  updateForm: (id, updates) => {
    set((state) => ({
      forms: state.forms.map((form) =>
        form.id === id ? { ...form, ...updates, updatedAt: new Date().toISOString() } : form,
      ),
    }))
  },

  deleteForm: (id) => {
    set((state) => ({
      forms: state.forms.filter((form) => form.id !== id),
      submissions: state.submissions.filter((sub) => sub.formId !== id),
    }))
  },

  duplicateForm: (id) => {
    const form = get().forms.find((f) => f.id === id)
    if (!form) return undefined

    const duplicated: Form = {
      ...form,
      id: `form-${Date.now()}`,
      title: `${form.title} (Copy)`,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      status: "draft",
    }

    set((state) => ({
      forms: [...state.forms, duplicated],
    }))

    return duplicated
  },

  addSubmission: (submissionData) => {
    const newSubmission: Submission = {
      ...submissionData,
      id: `sub-${Date.now()}`,
      submittedAt: new Date().toISOString(),
    }

    set((state) => ({
      submissions: [...state.submissions, newSubmission],
    }))

    return newSubmission
  },
}))
