"use client";

import { useState, useEffect } from "react";
import { useParams, useRouter } from "next/navigation";
import { useFormsStore } from "@/lib/forms-store";
import {
  DndContext,
  DragOverlay,
  closestCenter,
  PointerSensor,
  useSensor,
  useSensors,
  type DragStartEvent,
  type DragEndEvent,
  type DragOverEvent,
  defaultDropAnimationSideEffects,
  type DropAnimation,
} from "@dnd-kit/core";
import {
  SortableContext,
  verticalListSortingStrategy,
  arrayMove,
} from "@dnd-kit/sortable";
import { ArrowLeft, Save, Plus, Loader2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { useToast } from "@/hooks/use-toast";
import type { Section, Field, FieldType } from "@/types";

// Custom Components
import { BuilderSection } from "./_components/builder-section";
import { FieldCard } from "./_components/field-card";

// Animation config for smoother drops
const dropAnimationConfig: DropAnimation = {
  sideEffects: defaultDropAnimationSideEffects({
    styles: {
      active: { opacity: "0.5" },
    },
  }),
};

export default function BuilderPage() {
  const { id } = useParams<{ id: string }>();
  const router = useRouter();
  const { toast } = useToast();
  const { getFormById, updateForm } = useFormsStore();

  const form = getFormById(id);

  // --- State ---
  const [sections, setSections] = useState<Section[]>([]);
  // We track the active item ID and its Type (section or field) for the DragOverlay
  const [activeId, setActiveId] = useState<string | null>(null);
  const [activeItem, setActiveItem] = useState<Section | Field | null>(null);

  // Load initial data
  useEffect(() => {
    if (form) {
      setSections(form.content);
    }
  }, [form]);

  // --- Sensors ---
  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: {
        distance: 8, // Prevents accidental drags when clicking inputs
      },
    })
  );

  // --- CRUD Handlers ---

  const handleSave = () => {
    if (!form) return;
    updateForm(id, { ...form, content: sections });
    toast({ title: "Saved", description: "Form layout saved successfully." });
  };

  const handleAddSection = () => {
    const newSection: Section = {
      id: `section-${Date.now()}`,
      title: "Untitled Section",
      description: "",
      fields: [],
    };
    setSections([...sections, newSection]);
  };

  const handleDeleteSection = (sectionId: string) => {
    setSections((prev) => prev.filter((s) => s.id !== sectionId));
  };

  const handleUpdateSection = (
    sectionId: string,
    updates: Partial<Section>
  ) => {
    setSections((prev) =>
      prev.map((s) => (s.id === sectionId ? { ...s, ...updates } : s))
    );
  };

  const handleAddField = (sectionId: string, type: FieldType) => {
    const newField: Field = {
      id: `field-${Date.now()}`,
      type,
      title: type === "text" ? "Untitled Question" : `New ${type}`,
      required: false,
      options: ["select", "radio", "checkbox"].includes(type)
        ? ["Option 1", "Option 2"]
        : undefined,
    };

    setSections((prev) =>
      prev.map((s) => {
        if (s.id !== sectionId) return s;
        return { ...s, fields: [...s.fields, newField] };
      })
    );
  };

  const handleUpdateField = (fieldId: string, updates: Partial<Field>) => {
    setSections((prev) =>
      prev.map((s) => ({
        ...s,
        fields: s.fields.map((f) =>
          f.id === fieldId ? { ...f, ...updates } : f
        ),
      }))
    );
  };

  const handleDeleteField = (fieldId: string) => {
    setSections((prev) =>
      prev.map((s) => ({
        ...s,
        fields: s.fields.filter((f) => f.id !== fieldId),
      }))
    );
  };

  // --- Drag and Drop Logic ---

  // Helper to find which section a field belongs to
  const findSectionContainer = (id: string): Section | undefined => {
    return sections.find((s) => s.fields.some((f) => f.id === id));
  };

  const handleDragStart = (event: DragStartEvent) => {
    const { active } = event;
    const id = active.id as string;
    setActiveId(id);

    // Identify if we are dragging a Section or a Field
    const section = sections.find((s) => s.id === id);
    if (section) {
      setActiveItem(section);
      return;
    }

    const fieldSection = findSectionContainer(id);
    const field = fieldSection?.fields.find((f) => f.id === id);
    if (field) {
      setActiveItem(field);
    }
  };

  const handleDragOver = (event: DragOverEvent) => {
    const { active, over } = event;
    if (!over) return;

    const activeId = active.id as string;
    const overId = over.id as string;

    // If dragging a Section, ignore (handled in dragEnd)
    if (sections.some((s) => s.id === activeId)) return;

    // We are dragging a Field
    const activeSection = findSectionContainer(activeId);
    const overSection =
      findSectionContainer(overId) || sections.find((s) => s.id === overId);

    if (!activeSection || !overSection) return;

    // Moving between different sections
    if (activeSection.id !== overSection.id) {
      setSections((prev) => {
        const activeSecIndex = prev.findIndex((s) => s.id === activeSection.id);
        const overSecIndex = prev.findIndex((s) => s.id === overSection.id);

        return prev.map((section, index) => {
          if (index === activeSecIndex) {
            // Remove from source
            return {
              ...section,
              fields: section.fields.filter((f) => f.id !== activeId),
            };
          } else if (index === overSecIndex) {
            // Add to target (simple logic: add to end, or calculate index if needed)
            // Real-time calculation of index is complex, so we append for now during DragOver
            // A more robust implementation involves calculating the index based on Y coordinates
            const activeField = activeSection.fields.find(
              (f) => f.id === activeId
            )!;
            // Check if already added to prevent dupes during drag
            if (section.fields.some((f) => f.id === activeId)) return section;
            return {
              ...section,
              fields: [...section.fields, activeField],
            };
          }
          return section;
        });
      });
    }
  };

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;
    setActiveId(null);
    setActiveItem(null);

    if (!over) return;

    const activeId = active.id as string;
    const overId = over.id as string;

    if (activeId === overId) return;

    // 1. Handling Section Sorting
    const activeSectionIndex = sections.findIndex((s) => s.id === activeId);
    if (activeSectionIndex !== -1) {
      const overSectionIndex = sections.findIndex((s) => s.id === overId);
      if (overSectionIndex !== -1) {
        setSections((prev) =>
          arrayMove(prev, activeSectionIndex, overSectionIndex)
        );
      }
      return;
    }

    // 2. Handling Field Sorting (within same section)
    const activeContainer = findSectionContainer(activeId);
    const overContainer = findSectionContainer(overId);

    if (
      activeContainer &&
      overContainer &&
      activeContainer.id === overContainer.id
    ) {
      const activeIndex = activeContainer.fields.findIndex(
        (f) => f.id === activeId
      );
      const overIndex = activeContainer.fields.findIndex(
        (f) => f.id === overId
      );

      if (activeIndex !== overIndex) {
        setSections((prev) =>
          prev.map((s) => {
            if (s.id === activeContainer.id) {
              return {
                ...s,
                fields: arrayMove(s.fields, activeIndex, overIndex),
              };
            }
            return s;
          })
        );
      }
    }
  };

  if (!form) {
    return (
      <div className="h-screen w-full flex items-center justify-center">
        <Loader2 className="animate-spin w-8 h-8 text-primary" />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-muted/5 flex flex-col">
      {/* --- Top Navigation --- */}
      <header className="sticky top-0 z-20 border-b bg-background/95 backdrop-blur supports-backdrop-filter:bg-background/60">
        <div className="container max-w-3xl mx-auto h-14 flex items-center justify-between px-4">
          <div className="flex items-center gap-2">
            <Button
              variant="ghost"
              size="sm"
              className="-ml-2 text-muted-foreground"
              onClick={() => router.back()}
            >
              <ArrowLeft className="w-4 h-4 mr-1" />
              Back
            </Button>
            <div className="h-4 w-px bg-border mx-2" />
            <span className="font-semibold text-sm">{form.title}</span>
          </div>
          <Button size="sm" onClick={handleSave}>
            <Save className="w-4 h-4 mr-2" />
            Save Changes
          </Button>
        </div>
      </header>

      {/* --- Main Canvas --- */}
      <main className="flex-1 container max-w-3xl mx-auto py-8 px-4">
        <DndContext
          sensors={sensors}
          collisionDetection={closestCenter}
          onDragStart={handleDragStart}
          onDragOver={handleDragOver}
          onDragEnd={handleDragEnd}
        >
          {/* Sortable Context for Sections */}
          <SortableContext
            items={sections.map((s) => s.id)}
            strategy={verticalListSortingStrategy}
          >
            <div className="space-y-6 pb-20">
              {sections.length === 0 && (
                <div className="text-center py-10 border-2 border-dashed rounded-xl bg-card">
                  <p className="text-muted-foreground mb-4">
                    Your form is empty. Start by adding a section.
                  </p>
                  <Button onClick={handleAddSection}>Add Section</Button>
                </div>
              )}

              {sections.map((section) => (
                <BuilderSection
                  key={section.id}
                  section={section}
                  onUpdate={(updates) =>
                    handleUpdateSection(section.id, updates)
                  }
                  onDelete={() => handleDeleteSection(section.id)}
                  onAddField={(type) => handleAddField(section.id, type)}
                  onUpdateField={handleUpdateField}
                  onDeleteField={handleDeleteField}
                />
              ))}

              {/* Bottom "Add Section" Button */}
              {sections.length > 0 && (
                <div className="flex justify-center pt-4 opacity-0 hover:opacity-100 transition-opacity">
                  <Button
                    variant="ghost"
                    size="sm"
                    className="text-muted-foreground"
                    onClick={handleAddSection}
                  >
                    <Plus className="w-4 h-4 mr-2" />
                    Add Section
                  </Button>
                </div>
              )}
            </div>
          </SortableContext>

          {/* --- Drag Overlay (Preview) --- */}
          <DragOverlay dropAnimation={dropAnimationConfig}>
            {activeId ? (
              // If dragging a Section
              sections.find((s) => s.id === activeId) ? (
                <div className="opacity-90 rotate-2 cursor-grabbing">
                  <BuilderSection
                    section={activeItem as Section}
                    onUpdate={() => {}}
                    onDelete={() => {}}
                    onAddField={() => {}}
                    onUpdateField={() => {}}
                    onDeleteField={() => {}}
                  />
                </div>
              ) : (
                // If dragging a Field
                <div className="opacity-90 rotate-2 cursor-grabbing w-[600px]">
                  <FieldCard
                    field={activeItem as Field}
                    onUpdate={() => {}}
                    onDelete={() => {}}
                  />
                </div>
              )
            ) : null}
          </DragOverlay>
        </DndContext>
      </main>
    </div>
  );
}
